-- Accept one reviewed source-only successor; do not move or edit content.
-- Self-contained transaction. The release check keeps both complete predicates.
begin;
set local statement_timeout='20000ms';
set local lock_timeout='3000ms';
lock table public.trait,public.content_update in share row exclusive mode;
select id from public.content_source where id in(3,15) order by id for share;
do $incarnate_compatibility$
begin
 if not coalesce((((select exists(select 1 from public.trait t where t.id=2584 and to_jsonb(t)-'updated_at'-'search_tsv'=$incarnate_before${"id":2584,"created_at":"2024-04-19T02:01:06.796453+00:00","name":"Incarnate","description":"A spell with the incarnate trait is similar in theme to spells that summon creatures, but it doesn’t conjure a [minion](link_trait_2527) with the [summoned](link_trait_2134) trait. Instead, when summoned, the incarnate creature takes its Arrive action when you finish [Casting the Spell](link_action_19611). At the end of your next turn, the incarnate creature can either [Step](link_action_19853), [Stride](link_action_19855), or take the action for another movement type it has (such as [Climb](link_action_19612) or [Burrow](link_action_19609)), and then takes its Depart action. The spell then ends. The names of specific Arrive and Depart actions are listed in italics after the word “Arrive” or “Depart” respectively, along with any traits.\n\nA creature summoned by an incarnate spell acts in your interests, directs its effects away from you and your allies as much as possible, and might listen to your requests, but ultimately makes its own decisions. If the spell indicates that the incarnate makes a decision, the GM determines what the incarnate would do. It might even become more inclined to do precisely as you wish over multiple summonings.\n\nThe incarnate is not fully a creature. It can’t take any other actions, nor can it be targeted or harmed by [Strikes](link_action_19856), spells, or other effects unless they would be able to target or end a spell effect (such as [dispel magic](link_spell_4572)). It has a size for the purposes of determining its placement for effects, but it doesn’t block movement. If applicable, its effects use your spell DCs and spell attack modifier.","meta_data":{"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":15,"uuid":3690091311596588}$incarnate_before$::jsonb)
 and exists(select 1 from public.content_source s where s.id=3 and s.name='Common Core' and s.user_id is null and s.is_published is true and s.deprecated is not true)
 and not exists(select 1 from public.trait t where t.id<>2584 and (t.uuid=3690091311596588 or (t.content_source_id in(3,15) and lower(pg_catalog.regexp_replace(coalesce(t.name,''),'^[[:space:]]+|[[:space:]]+$','','g'))='incarnate')))
 and not exists(select 1 from public.content_update u where upper(pg_catalog.regexp_replace(coalesce(u.status->>'state',''),'^[[:space:]]+|[[:space:]]+$','','g')) not in('APPROVED','REJECTED') and replace(lower(pg_catalog.regexp_replace(coalesce(u.type,''),'^[[:space:]]+|[[:space:]]+$','','g')),'_','-')='trait'
   and (u.ref_id=2584 or pg_catalog.regexp_replace(coalesce(u.data->>'id',''),'^[[:space:]]+|[[:space:]]+$','','g')='2584' or pg_catalog.regexp_replace(coalesce(u.data->>'uuid',''),'^[[:space:]]+|[[:space:]]+$','','g')='3690091311596588'
    or (lower(pg_catalog.regexp_replace(coalesce(u.data->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))='incarnate' and (u.content_source_id in(3,15) or pg_catalog.regexp_replace(coalesce(u.data->>'content_source_id',''),'^[[:space:]]+|[[:space:]]+$','','g') in('3','15')))))) or (select exists(select 1 from public.trait t where t.id=2584 and to_jsonb(t)-'updated_at'-'search_tsv'=$incarnate_after${"id":2584,"created_at":"2024-04-19T02:01:06.796453+00:00","name":"Incarnate","description":"A spell with the incarnate trait is similar in theme to spells that summon creatures, but it doesn’t conjure a [minion](link_trait_2527) with the [summoned](link_trait_2134) trait. Instead, when summoned, the incarnate creature takes its Arrive action when you finish [Casting the Spell](link_action_19611). At the end of your next turn, the incarnate creature can either [Step](link_action_19853), [Stride](link_action_19855), or take the action for another movement type it has (such as [Climb](link_action_19612) or [Burrow](link_action_19609)), and then takes its Depart action. The spell then ends. The names of specific Arrive and Depart actions are listed in italics after the word “Arrive” or “Depart” respectively, along with any traits.\n\nA creature summoned by an incarnate spell acts in your interests, directs its effects away from you and your allies as much as possible, and might listen to your requests, but ultimately makes its own decisions. If the spell indicates that the incarnate makes a decision, the GM determines what the incarnate would do. It might even become more inclined to do precisely as you wish over multiple summonings.\n\nThe incarnate is not fully a creature. It can’t take any other actions, nor can it be targeted or harmed by [Strikes](link_action_19856), spells, or other effects unless they would be able to target or end a spell effect (such as [dispel magic](link_spell_4572)). It has a size for the purposes of determining its placement for effects, but it doesn’t block movement. If applicable, its effects use your spell DCs and spell attack modifier.","meta_data":{"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3690091311596588}$incarnate_after$::jsonb)
 and exists(select 1 from public.content_source s where s.id=3 and s.name='Common Core' and s.user_id is null and s.is_published is true and s.deprecated is not true)
 and not exists(select 1 from public.trait t where t.id<>2584 and (t.uuid=3690091311596588 or (t.content_source_id in(3,15) and lower(pg_catalog.regexp_replace(coalesce(t.name,''),'^[[:space:]]+|[[:space:]]+$','','g'))='incarnate')))
 and not exists(select 1 from public.content_update u where upper(pg_catalog.regexp_replace(coalesce(u.status->>'state',''),'^[[:space:]]+|[[:space:]]+$','','g')) not in('APPROVED','REJECTED') and replace(lower(pg_catalog.regexp_replace(coalesce(u.type,''),'^[[:space:]]+|[[:space:]]+$','','g')),'_','-')='trait'
   and (u.ref_id=2584 or pg_catalog.regexp_replace(coalesce(u.data->>'id',''),'^[[:space:]]+|[[:space:]]+$','','g')='2584' or pg_catalog.regexp_replace(coalesce(u.data->>'uuid',''),'^[[:space:]]+|[[:space:]]+$','','g')='3690091311596588'
    or (lower(pg_catalog.regexp_replace(coalesce(u.data->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))='incarnate' and (u.content_source_id in(3,15) or pg_catalog.regexp_replace(coalesce(u.data->>'content_source_id',''),'^[[:space:]]+|[[:space:]]+$','','g') in('3','15'))))))) and not exists(select 1 from public.content_update u
 where upper(pg_catalog.regexp_replace(coalesce(u.status->>'state',''),'^[[:space:]]+|[[:space:]]+$','','g')) not in('APPROVED','REJECTED')
 and replace(lower(pg_catalog.regexp_replace(coalesce(u.type,''),'^[[:space:]]+|[[:space:]]+$','','g')),'_','-')='trait'
 and (u.ref_id=2584 or pg_catalog.regexp_replace(coalesce(u.data->>'id',''),'^[[:space:]]+|[[:space:]]+$','','g')='2584'
  or pg_catalog.regexp_replace(coalesce(u.data->>'uuid',''),'^[[:space:]]+|[[:space:]]+$','','g')='3690091311596588'
  or (lower(pg_catalog.regexp_replace(coalesce(u.data->>'name',''),'^[[:space:]]+|[[:space:]]+$','','g'))='incarnate'
   and (u.content_source_id in(3,15) or exists(select 1 from jsonb_array_elements(jsonb_build_array(u.data->>'content_source_id',u.data->>'source_id',u.data#>>'{source,content_source_id}',u.data#>>'{source,source_id}',u.data#>>'{source,id}',u.data#>>'{meta_data,content_source_id}',u.data#>>'{meta_data,source,content_source_id}',u.data#>>'{meta_data,source,source_id}')) x
    where pg_catalog.regexp_replace(coalesce(x#>>'{}',''),'^[[:space:]]+|[[:space:]]+$','','g') in('3','15'))))))),false) then
   raise exception 'Incarnate source-only compatibility differs';
 end if;
end $incarnate_compatibility$;
